<script setup lang="ts">
import{ref,onMounted,onUnmounted,watch}from'vue';import{useRoute}from'vue-router';import{request,post}from'../api/client';import{ElMessageBox}from'element-plus';import PluginRenderer from'../components/PluginRenderer.vue'
const frame=ref<HTMLIFrameElement|null>(null)
const route=useRoute(),plugin=ref<any>(null),value=ref<any>(null),busy=ref(false),error=ref('')
async function load(){busy.value=true;error.value='';try{const list=await request<any[]>('/plugins');plugin.value=list.find(x=>x.manifest.id===route.params.id);if(!plugin.value?.enabled)throw new Error('插件未启用，请核对配置并明确授权');value.value=await request(`/plugins/${route.params.id}/view/page/${route.params.page}`)}catch(e){value.value=null;error.value=String(e)}finally{busy.value=false}}
async function command(id:string,data:Record<string,unknown>={}){if(!plugin.value?.manifest.commands?.some((x:any)=>x.id===id)){error.value='插件未声明该命令';return false};try{await ElMessageBox.confirm('明确执行插件命令？可能触发已授权的外部访问或通知，不会自动重试。','执行插件命令',{confirmButtonText:'确认执行',cancelButtonText:'取消'});await post(`/plugins/${route.params.id}/view/command/${id}`,{confirm:true,data});await load();return true}catch(e){if(e instanceof Error)error.value=e.message;return false}}
async function bridge(event:MessageEvent){if(event.source!==frame.value?.contentWindow||!plugin.value?.enabled)return;const message=event.data;if(!message||message.type!=='media-tool-plugin'||typeof message.requestId!=='string')return;let response:any={};try{if(message.action==='data')response=await request(`/plugins/${route.params.id}/state`);else if(message.action==='api'){if(!plugin.value.manifest.routes?.some((x:any)=>x.path===message.path&&x.method==='GET'))throw new Error('未声明的API');response=await request(`/plugins/${route.params.id}/view/api/${message.path}`)}else if(message.action==='command'){response={executed:await command(message.id,message.data??{})}}else throw new Error('未支持的桥接操作');frame.value?.contentWindow?.postMessage({type:'media-tool-plugin-result',requestId:message.requestId,data:response},'*')}catch(e){frame.value?.contentWindow?.postMessage({type:'media-tool-plugin-result',requestId:message.requestId,error:String(e)},'*')}}
onMounted(()=>{load();window.addEventListener('message',bridge)});onUnmounted(()=>window.removeEventListener('message',bridge));watch(()=>route.fullPath,load)
</script>
<template><section class="page-heading"><div><span class="page-kicker">SYSTEM / 插件应用</span><h1>{{plugin?.manifest.name||'插件应用'}}</h1><p>独立插件页面 · 宿主权限与命令均按安装包声明</p></div><RouterLink to="/plugins" class="inline-link">返回插件管理</RouterLink></section><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><el-button :loading="busy" @click="load">刷新插件页面</el-button><iframe v-if="plugin?.manifest.customUI&&plugin?.enabled" ref="frame" :src="`/api/v1/plugins/${route.params.id}/ui`" sandbox="allow-scripts" title="插件独立界面" class="plugin-frame"/><PluginRenderer v-if="value" :value="value" @command="command"/><div class="plugin-commands"><el-button v-for="cmd in plugin?.manifest.commands??[]" :key="cmd.id" :disabled="!plugin?.enabled||busy" @click="command(cmd.id)">{{cmd.name}}</el-button></div></section></template>
<style scoped>.plugin-frame{width:100%;min-height:480px;border:1px solid var(--border);border-radius:8px;margin-top:16px}.plugin-commands{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}</style>
